using System;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
class StockDemand {public int Grade,Diameter;public long Pieces;public double Cut,Lap;}
class StockChoice {public double Length,Cut,Lap;public long Required,PiecesPerStock,Bars,Segments=1;public double SpliceMetres{get{return Required*(Segments-1)*Lap;}}public double SegmentCut{get{return (Cut+(Segments-1)*Lap)/Segments;}}public double Purchased{get{return Bars*Length;}}public double Used{get{return Required*Cut+SpliceMetres;}}public double Waste{get{return Math.Max(0,Purchased-Used);}}}
class StockAllocation {public EstimateInput Entry;public EstimateLine Line;public StockDemand Demand;public StockChoice Choice;public double Purchase,Splice,Waste;public double Net{get{return Demand.Cut*Demand.Pieces*EstimatorEngine.UnitMass(Demand.Diameter);}}}
static class CommercialBars {
 public static List<StockAllocation> Allocate(IEnumerable<EstimateInput> inputs,LengthConfiguration config,IEnumerable<double> available=null){
  var rows=new List<StockAllocation>();foreach(var entry in inputs.Where(i=>i.Result!=null))foreach(var line in entry.Result.Lines){var single=new EstimateInput{Quantity=entry.Quantity,Result=new BeamEstimate()};single.Result.Lines.Add(line);foreach(var demand in Demands(new[]{single},config))rows.Add(new StockAllocation{Entry=entry,Line=line,Demand=demand});}
  foreach(var group in rows.GroupBy(a=>new{a.Demand.Grade,a.Demand.Diameter,a.Demand.Cut,a.Demand.Lap})){long count=group.Sum(a=>a.Demand.Pieces);var best=Best(Choices(group.Key.Cut,count,group.Key.Lap,available));if(best==null)continue;double mass=EstimatorEngine.UnitMass(group.Key.Diameter),remainingBuy=best.Purchased*mass,remainingSplice=best.SpliceMetres*mass,remainingWaste=best.Waste*mass;var members=group.ToList();for(int n=0;n<members.Count;n++){var a=members[n];double share=(double)a.Demand.Pieces/count;a.Choice=best;a.Purchase=n==members.Count-1?remainingBuy:best.Purchased*mass*share;a.Splice=n==members.Count-1?remainingSplice:best.SpliceMetres*mass*share;a.Waste=n==members.Count-1?remainingWaste:best.Waste*mass*share;remainingBuy-=a.Purchase;remainingSplice-=a.Splice;remainingWaste-=a.Waste;}}
  return rows;
 }

 public static readonly double[] Lengths={6,7.5,9,10.5,12,13.5,15};
 public static List<double> Available(IEnumerable<double> values){var list=(values??Lengths).Distinct().OrderBy(x=>x).ToList();if(list.Count==0||list.Any(x=>!Lengths.Contains(x)))throw new ArgumentException("Select at least one supported commercial length.");return list;}
 public static string FormatLengths(IEnumerable<double> values){return string.Join(",",values.Select(v=>v.ToString("0.##",CultureInfo.InvariantCulture)));}
 public static List<double> ParseLengths(string text){return string.IsNullOrWhiteSpace(text)?Available(null):Available(text.Split(',').Select(x=>double.Parse(x,CultureInfo.InvariantCulture)));}
 public static List<StockChoice> Choices(double cut,long pieces,double lap=0,IEnumerable<double> available=null){
  if(double.IsNaN(cut)||double.IsInfinity(cut)||cut<=0||pieces<=0)throw new ArgumentException("Invalid stock cutting demand.");
  var rows=new List<StockChoice>();foreach(double stock in Available(available)){if(cut>stock){if(lap<=0||lap>=stock||double.IsNaN(lap)||double.IsInfinity(lap))continue;long segments=(long)Math.Ceiling((cut-lap)/(stock-lap));while((cut+(segments-1)*lap)/segments>stock)segments++;rows.Add(new StockChoice{Length=stock,Cut=cut,Lap=lap,Segments=segments,Required=pieces,PiecesPerStock=1,Bars=checked(pieces*segments)});continue;}long fit=(long)Math.Floor(stock/cut);if(fit<1)continue;while(fit>0&&fit*cut>stock)fit--;if(fit==0)continue;long bars=pieces/fit+(pieces%fit==0?0:1);rows.Add(new StockChoice{Length=stock,Cut=cut,Required=pieces,PiecesPerStock=fit,Bars=bars});}return rows;
 }
 public static StockChoice Best(IEnumerable<StockChoice> choices){return choices.OrderBy(c=>Math.Round(c.Waste,9)).ThenBy(c=>c.Bars).ThenBy(c=>c.Length).FirstOrDefault();}
 public static List<StockDemand> Demands(IEnumerable<EstimateInput> inputs,LengthConfiguration configuration=null){
  var result=new List<StockDemand>();foreach(var i in inputs.Where(x=>x.Result!=null)){long quantity=long.Parse(i.Quantity,CultureInfo.InvariantCulture);foreach(var line in i.Result.Lines){Action<double,long> add=(cut,n)=>{if(n>0&&cut>0)result.Add(new StockDemand{Grade=line.Grade,Diameter=line.Diameter,Cut=cut,Pieces=n,Lap=cut>6&&line.Part!="Stirrups"&&configuration!=null?configuration.Rounded(configuration.Values(line.Diameter,line.Part.StartsWith("Top")).Lap)/1000:0});};
   if(line.Part=="Stirrups"){long sets=checked((long)line.TieSetsPerBeam*quantity);if(line.TieOverride)add(line.CutLength,sets);else{add(line.MainHoopCut,sets);add(line.AdditionalLegCut,checked(sets*line.AdditionalLegs));}}
   else add(line.CutLength,checked((long)line.PiecesPerBeam*quantity));
  }}return result.GroupBy(d=>new{d.Grade,d.Diameter,d.Cut,d.Lap}).Select(g=>new StockDemand{Grade=g.Key.Grade,Diameter=g.Key.Diameter,Cut=g.Key.Cut,Lap=g.Key.Lap,Pieces=g.Sum(x=>x.Pieces)}).OrderBy(d=>d.Grade).ThenBy(d=>d.Diameter).ThenByDescending(d=>d.Cut).ToList();
 }
 public static string Report(IEnumerable<EstimateInput> inputs,LengthConfiguration configuration=null,IEnumerable<double> available=null){
  var b=new StringBuilder();var chosen=new List<KeyValuePair<StockDemand,StockChoice>>();int unmatched=0;
  b.AppendLine("COMMERCIAL REBAR CUTTING / PURCHASE PLAN");b.AppendLine("Available stock lengths: "+FormatLengths(Available(available))+" m.");b.AppendLine("Minimum TOTAL unused metres wins; ties: fewer stock bars, then shorter stock.");b.AppendLine("Whole pieces only. Full-precision cuts; displayed values have 2 decimals.");b.AppendLine("Identical cuts pooled across entries; grades/diameters kept separate.");b.AppendLine("Offcuts are not reused between different cut lengths. Cutting kerf assumed zero.");b.AppendLine("This is a per-cut stock comparison, not a mixed-length cutting optimization.");b.AppendLine("No manual wastage percentage. Purchase includes required cuts, added splice laps and stock offcuts.");
  foreach(var d in Demands(inputs,configuration)){b.AppendLine();b.AppendLine(string.Format(CultureInfo.InvariantCulture,"G{0} D{1} | cut {2:0.00} m | required {3} pieces",d.Grade,d.Diameter,d.Cut,d.Pieces));var choices=Choices(d.Cut,d.Pieces,d.Lap,available);var best=Best(choices);if(best==null){unmatched++;b.AppendLine("REVIEW: oversized cut requires valid lap configuration (main/SFR only).");continue;}chosen.Add(new KeyValuePair<StockDemand,StockChoice>(d,best));b.AppendLine(string.Format("{0,8}{1,10}{2,10}{3,14}{4,13}{5,11}","STOCK m","PCS/STOCK","BUY PCS","BUY m","WASTE m","WASTE %"));foreach(double length in Available(available)){var c=choices.FirstOrDefault(x=>x.Length==length);if(c==null){b.AppendLine(length.ToString("0.00",CultureInfo.InvariantCulture)+" m: cut does not fit");continue;}b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,8:0.00}{1,10}{2,10}{3,14:0.00}{4,13:0.00}{5,11:0.00}{6}",c.Length,c.PiecesPerStock,c.Bars,c.Purchased,c.Waste,100*c.Waste/c.Purchased,c==best?" * SELECTED":""));if(c.Segments>1)b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Per original piece: {0} segments x {1:0.00}m; {2} lap(s) x {3:0.00}m; added lap total {4:0.00}m",c.Segments,c.SegmentCut,c.Segments-1,c.Lap,c.SpliceMetres));}}
  b.AppendLine();b.AppendLine("SELECTED STOCK PURCHASE SUMMARY");b.AppendLine(string.Format("{0,-8}{1,6}{2,10}{3,10}{4,14}{5,14}","GRADE","DIA","STOCK m","BUY PCS","BUY kg","WASTE kg"));foreach(var group in chosen.GroupBy(x=>new{x.Key.Grade,x.Key.Diameter,x.Value.Length})){double mass=EstimatorEngine.UnitMass(group.Key.Diameter);b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-8}{1,6}{2,10:0.00}{3,10}{4,14:0.00}{5,14:0.00}","G"+group.Key.Grade,group.Key.Diameter,group.Key.Length,group.Sum(x=>x.Value.Bars),group.Sum(x=>x.Value.Purchased)*mass,group.Sum(x=>x.Value.Waste)*mass));}
  foreach(int grade in new[]{40,60})b.AppendLine(string.Format(CultureInfo.InvariantCulture,"GRADE {0}: BUY {1:0.00} kg | STOCK WASTE {2:0.00} kg",grade,chosen.Where(x=>x.Key.Grade==grade).Sum(x=>x.Value.Purchased*EstimatorEngine.UnitMass(x.Key.Diameter)),chosen.Where(x=>x.Key.Grade==grade).Sum(x=>x.Value.Waste*EstimatorEngine.UnitMass(x.Key.Diameter))));
  b.AppendLine("ADDITIONAL SPLICE STEEL: "+chosen.Sum(x=>x.Value.SpliceMetres*EstimatorEngine.UnitMass(x.Key.Diameter)).ToString("0.00",CultureInfo.InvariantCulture)+" kg");b.AppendLine("Splice quantity allowance only: actual splice locations/staggering require structural detailing.");b.AppendLine("TOTAL PURCHASE: "+chosen.Sum(x=>x.Value.Purchased*EstimatorEngine.UnitMass(x.Key.Diameter)).ToString("0.00",CultureInfo.InvariantCulture)+" kg");if(unmatched>0)b.AppendLine("PARTIAL PURCHASE PLAN: "+unmatched+" cut demand(s) require review and are excluded.");return b.ToString();
 }
}
}
